using Meziantou.Framework.Imaging.TestHarness.Adapters;
using Meziantou.Framework.Imaging.TestHarness.Fixtures;
using Meziantou.Framework.Imaging.TestHarness.Golden;
using Meziantou.Framework.Imaging.TestHarness.Pixels;
using Meziantou.Framework.Imaging.TestHarness.Pnm;

namespace Meziantou.Framework.Imaging.Tests.Conformance;

/// <summary>
/// Netpbm decoding against the corpus generated by <c>tools/Meziantou.Framework.Imaging.CorpusGenerator/PnmCorpus.cs</c>: files
/// assembled byte by byte with literal samples, plus files produced by FFmpeg's independent PPM and PAM encoders. These
/// tests check that the fixtures cover every magic number, tuple type and precision, that decoding is exact,
/// that the plain and binary forms of the same image agree, that <c>MAXVAL</c> normalization is the exact ratio, and that
/// the independent harness reader agrees with the corpus and rejects every malformed fixture.
/// </summary>
public sealed class PnmDecoderConformanceTests
{
    public static TheoryData<string> ValidFixtures => [.. GoldenCorpus.Default.GetIds(format: "pnm", kind: FixtureKinds.Valid)];

    /// <summary>
    /// The malformed inputs, except the one the formats allow and only this library's bounded-header policy rejects
    /// (<see cref="TheBoundedHeaderRejectsAdversarialComments"/>).
    /// </summary>
    public static TheoryData<string> InvalidFixtures => [.. GoldenCorpus.Default.GetIds(format: "pnm", kind: FixtureKinds.Invalid)
        .Where(id => !string.Equals(id, HeaderTooLongFixture, StringComparison.Ordinal))];

    private const string HeaderTooLongFixture = "invalid/pnm/header-too-long";

    [Fact]
    public void FixturesCoverEveryDocumentedVariant()
    {
        var fixtures = GoldenCorpus.Default.GetIds(format: "pnm", kind: FixtureKinds.Valid).Select(GoldenCorpus.Default.Get).ToList();
        var features = fixtures.SelectMany(fixture => fixture.Entry.Features ?? []).ToHashSet(StringComparer.Ordinal);
        foreach (var feature in new[]
        {
            "pnm.magic=P1", "pnm.magic=P2", "pnm.magic=P3", "pnm.magic=P4", "pnm.magic=P5", "pnm.magic=P6", "pnm.magic=P7",
            "pnm.raster=plain", "pnm.raster=binary",
            "pnm.tuple=BLACKANDWHITE", "pnm.tuple=GRAYSCALE", "pnm.tuple=RGB", "pnm.tuple=GRAYSCALE_ALPHA", "pnm.tuple=RGB_ALPHA",
            "pnm.maxval=1", "pnm.maxval=255", "pnm.maxval=65535", "pnm.maxval.normalized",
            "pnm.comments", "pnm.pbm.rowPadding", "pnm.width=odd",
        })
        {
            Assert.Contains(feature, features);
        }

        Assert.Contains(fixtures, fixture => fixture.Entry.Provenance.Origin == "hand-authored");
        Assert.Contains(fixtures, fixture => fixture.Entry.Provenance.Commands?.Any(command => command.StartsWith("ffmpeg", StringComparison.Ordinal)) == true);
        Assert.All(fixtures, fixture => Assert.True(fixture.Policy.IsExact, fixture.Id));
    }

    [Theory]
    [MemberData(nameof(ValidFixtures))]
    public void DecodingIsExactInEveryRepresentation(string id)
    {
        var fixture = GoldenCorpus.Default.Get(id);
        var data = fixture.ReadInput();

        // 8-bit fixtures are compared in Rgba32, 16-bit ones in Rgba64: the canonical layout of their references
        if (fixture.CanonicalLayout == RawPixelLayout.Rgba16Le)
        {
            using var image = Image.Load<Rgba64>(data);
            Assert.True(fixture.GetFrame(0, RawPixelLayout.Rgba16Le).Span.SequenceEqual(ImageSnapshots.CaptureFrame(image.Frames[0]).Span), $"{id}: differs from the reference.");
        }
        else
        {
            using var image = Image.Load<Rgba32>(data);
            Assert.True(fixture.GetFrame(0, RawPixelLayout.Rgba8).Span.SequenceEqual(ImageSnapshots.CaptureFrame(image.Frames[0]).Span), $"{id}: differs from the reference.");
        }

        using (var image = Image.Load(data))
        {
            Assert.Equal(fixture.Expected.PixelFormat, image.PixelFormat.ToString());
            var layout = image.PixelFormat switch
            {
                PixelFormat.Gray8 => RawPixelLayout.Gray8,
                PixelFormat.Gray16 => RawPixelLayout.Gray16Le,
                PixelFormat.Rgb24 => RawPixelLayout.Rgb8,
                PixelFormat.Rgba64 => RawPixelLayout.Rgba16Le,
                _ => RawPixelLayout.Rgba8,
            };

            var bytes = new byte[image.Width * image.Height * layout.BytesPerPixel];
            image.Frames[0].CopyPixelBytesTo(bytes);
            Assert.True(fixture.GetFrame(0, layout).Span.SequenceEqual(bytes), $"{id}: the {layout.Name} samples differ from the reference.");
        }
    }

    [Fact]
    public void ThePlainAndBinaryFormsOfTheSameImageAgree()
    {
        // A set bit of a PBM is black, in both the plain (P1) and the binary (P4) form
        using var plain = Image.Load<Rgba32>(GoldenCorpus.Default.Get("pnm/p1-plain-bitmap").ReadInput());
        using var binary = Image.Load<Rgba32>(GoldenCorpus.Default.Get("pnm/p4-bitmap-padding").ReadInput());
        Assert.True(ImageSnapshots.CaptureFrame(plain.Frames[0]).Span.SequenceEqual(ImageSnapshots.CaptureFrame(binary.Frames[0]).Span));
    }

    [Fact]
    public void ABlackAndWhitePamIsNotInvertedLikeAPbmBit()
    {
        // PAM BLACKANDWHITE samples are intensities (0 is black, 1 is white); a PBM bit is the opposite
        using var image = Image.Load<Gray8>(GoldenCorpus.Default.Get("pnm/p7-blackandwhite").ReadInput());
        var reference = ReferencePnm.Parse(GoldenCorpus.Default.Get("pnm/p7-blackandwhite").ReadInput());
        Assert.Equal("BLACKANDWHITE", reference.TupleType);
        var bytes = new byte[image.Width * image.Height];
        image.Frames[0].CopyPixelBytesTo(bytes);
        Assert.Equal(byte.MaxValue, bytes[0]); // the first sample is 1
    }

    [Theory]
    [MemberData(nameof(ValidFixtures))]
    public void TheReferenceReaderAgreesWithTheCorpus(string id)
    {
        var fixture = GoldenCorpus.Default.Get(id);
        var reference = ReferencePnm.Parse(fixture.ReadInput());
        Assert.Equal((fixture.Expected.Width, fixture.Expected.Height), (reference.Width, reference.Height));
        var expected = fixture.GetFrame(0, fixture.CanonicalLayout).Span;
        var actual = fixture.CanonicalLayout == RawPixelLayout.Rgba16Le ? reference.GetRgba16Le() : reference.GetRgba8();
        Assert.True(expected.SequenceEqual(actual), $"{id}: the harness reader differs from the corpus reference.");
    }

    [Fact]
    public void TheBoundedHeaderRejectsAdversarialComments()
    {
        // A 70,000-byte comment is legal Netpbm (the independent reader accepts it) but exceeds the documented 65,536-byte
        // header bound, so the header walk stays bounded instead of scanning an arbitrary amount of white space
        var data = GoldenCorpus.Default.Get(HeaderTooLongFixture).ReadInput();
        Assert.Equal(5, ReferencePnm.Parse(data).Width);
        var exception = Assert.Throws<InvalidImageContentException>(() => Image.Load(data));
        Assert.Equal(ImageFormat.Pnm, exception.Format);
    }

    [Theory]
    [MemberData(nameof(InvalidFixtures))]
    public void TheReferenceReaderRejectsEveryMalformedFixture(string id)
    {
        var fixture = GoldenCorpus.Default.Get(id);
        Assert.Throws<InvalidDataException>(() => ReferencePnm.Parse(fixture.ReadInput()));
        var exception = Assert.Throws<InvalidImageContentException>(() => Image.Load(fixture.ReadInput()));
        Assert.Equal(ImageFormat.Pnm, exception.Format);
    }
}
